import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Audit and Signature","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/forge/audit.md","filePath":"en/modules/forge/audit.md","lastUpdated":0}`),a={name:`en/modules/forge/audit.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="audit-and-signature" tabindex="-1">Audit and Signature <a class="header-anchor" href="#audit-and-signature" aria-label="Permalink to “Audit and Signature”">​</a></h1><p>EmakiForge writes audit data to forged result items after successful forging. This data helps trace the source recipe and validate whether material contribution data was tampered with.</p><h2 id="where-the-data-lives" tabindex="-1">Where the data lives <a class="header-anchor" href="#where-the-data-lives" aria-label="Permalink to “Where the data lives”">​</a></h2><p>Forge audit data exists in two places:</p><ol><li><strong>CoreLib item layer snapshot</strong>: namespace <code>forge</code>, layer version <code>1</code>, whose payload is the audit field table below (assembled by <code>ForgeLayerSnapshotBuilder</code>). Item refresh reads it back from here.</li><li><strong>The <code>emakiforge:forge</code> PDC partition</strong>: key fields flattened so the placeholder and variable systems can read them. See <a href="#forge-layer-pdc-keys">Forge layer PDC keys</a>.</li></ol><h2 id="audit-fields" tabindex="-1">Audit fields <a class="header-anchor" href="#audit-fields" aria-label="Permalink to “Audit fields”">​</a></h2><p>After a successful forge the following fields are written into the audit payload:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>schema</code></td><td>Audit structure marker, currently always <code>forge_audit_v2</code>.</td></tr><tr><td><code>schema_version</code></td><td>Audit structure version, currently <code>2</code>.</td></tr><tr><td><code>stage</code></td><td>Originating stage, currently always <code>forge</code>.</td></tr><tr><td><code>recipe_id</code></td><td>Recipe id used for forging.</td></tr><tr><td><code>quality</code></td><td>Quality tier name; an empty string when no tier resolved.</td></tr><tr><td><code>multiplier</code></td><td>Quality multiplier.</td></tr><tr><td><code>forged_at</code></td><td>Forge timestamp in milliseconds.</td></tr><tr><td><code>materials_signature</code></td><td>Stable hash signature of material contribution data.</td></tr><tr><td><code>output_item</code></td><td>Output item source shorthand. Written only when the recipe configures an output item source.</td></tr><tr><td><code>materials</code></td><td>Material contribution list, see the table below.</td></tr></tbody></table><p>Fields of each <code>materials[]</code> entry:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>material_id</code> / <code>count_key</code> / <code>audit_id</code></td><td>Material identity keys. Written only when declared explicitly in config; the key is removed when it was not declared.</td></tr><tr><td><code>material_item</code></td><td>Compatibility identity: the item source shorthand, or <code>matcher:&lt;digest&gt;</code>.</td></tr><tr><td><code>category</code></td><td>Material category (required / optional).</td></tr><tr><td><code>amount</code></td><td>Planned amount.</td></tr><tr><td><code>amount_consumed</code></td><td>Actually consumed amount.</td></tr><tr><td><code>slot</code></td><td>GUI slot the material occupied.</td></tr><tr><td><code>sequence</code></td><td>Processing order.</td></tr><tr><td><code>matched_source</code></td><td>Item source shorthand actually matched.</td></tr><tr><td><code>matcher</code></td><td>Matcher digest key; an empty string when there is no matcher.</td></tr><tr><td><code>allocation</code></td><td>Slot allocation detail for this entry.</td></tr><tr><td><code>legacy_identity</code> / <code>identity_diagnostic</code></td><td>Compatibility identity and diagnostic marker added when some identity key was not declared.</td></tr></tbody></table><h2 id="material-signature" tabindex="-1">Material signature <a class="header-anchor" href="#material-signature" aria-label="Permalink to “Material signature”">​</a></h2><p><code>materials_signature</code> is computed only from material contributions whose consumed amount is greater than zero; the signature input covers the material definition digest, amount, consumed amount, slot, category, sequence, matched source, and allocation detail. The same set of material contributions always yields the same signature, so it can be used to compare an item&#39;s forging material data against an expected value.</p><h2 id="forge-layer-pdc-keys" tabindex="-1">Forge layer PDC keys <a class="header-anchor" href="#forge-layer-pdc-keys" aria-label="Permalink to “Forge layer PDC keys”">​</a></h2><p>Flat keys under namespace <code>emakiforge</code>, partition <code>forge</code>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>forge_recipe_id</code></td><td>string</td><td>Recipe id that forged the item.</td></tr><tr><td><code>quality_id</code></td><td>string</td><td>Quality id (same value as the tier name).</td></tr><tr><td><code>quality_display</code></td><td>string</td><td>Quality display name.</td></tr><tr><td><code>quality_multiplier</code></td><td>string</td><td>Quality multiplier, stored formatted as <code>0.##</code>.</td></tr><tr><td><code>material_id</code></td><td>string</td><td>Comma-joined list of explicitly declared <code>material_id</code> values; removed when empty.</td></tr><tr><td><code>count_key</code></td><td>string</td><td>Comma-joined list of explicitly declared <code>count_key</code> values; removed when empty.</td></tr><tr><td><code>audit_id</code></td><td>string</td><td>Comma-joined list of explicitly declared <code>audit_id</code> values; removed when empty.</td></tr><tr><td><code>matched_source</code></td><td>string</td><td>Comma-joined list of matched source shorthands.</td></tr><tr><td><code>amount_consumed</code></td><td>integer</td><td>Total consumed amount across all materials.</td></tr><tr><td><code>matcher_digest</code></td><td>string</td><td>Comma-joined list of matcher digests.</td></tr><tr><td><code>allocation</code></td><td>string</td><td>Stable signature of the allocation detail.</td></tr></tbody></table><p>The CoreLib variable system exposes these as the variables <code>forge_quality_id</code>, <code>forge_quality_display</code>, <code>forge_quality_multiplier</code>, and <code>forge_recipe_id</code>, plus the partition-relative PDC strings.</p><h2 id="relationship-with-refresh" tabindex="-1">Relationship with refresh <a class="header-anchor" href="#relationship-with-refresh" aria-label="Permalink to “Relationship with refresh”">​</a></h2><p>The Forge item refresh service reads <code>recipe_id</code> and <code>quality</code> from the audit data to rebuild the forge layer presentation. Items whose audit data is missing, whose quality is no longer in the current pool, or whose recipe has been deleted cannot have their forge layer rebuilt and produce a warning.</p><p>When resolving material audit records, the current implementation falls back in this order: <code>audit_id</code> → <code>material_id</code> → <code>count_key</code> → legacy <code>material_item</code> / <code>source</code>. A successful legacy lookup is marked for migration and rebuilt during refresh; when no identity resolves, the original item is kept and a warning is logged rather than overwriting it with incomplete state. <strong>Material identity keys must stay stable</strong>: a matcher-only material derives its identity from the matcher content digest, so editing the matcher makes already-forged items report a missing material (<code>console.forge_refresh_missing_material</code>). This behaviour is established by source inspection, but old PDC audit data was not tested on a live Paper/Folia server in this cycle.</p><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use cases”">​</a></h2><ul><li>Trading or recycling systems can read audit data to determine an item&#39;s source recipe and quality.</li><li>External analytics can aggregate forge output by <code>recipe_id</code>, <code>quality</code>, and <code>forged_at</code>.</li></ul><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Forge does not ship a built-in command for viewing audit data. Use an external tool that can read item PDC and item layer snapshots when manual inspection is needed.</p></div>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};